:root {
  --navy: #0a1628;
  --navy-2: #12233f;
  --accent: #0f8b8d;
  --accent-gold: #c8a96a;
  --white: #ffffff;
  --gray-50: #f5f7fa;
  --gray-100: #e9edf2;
  --gray-200: #d5dce5;
  --gray-500: #5d6b7a;
  --gray-700: #324054;
  --text: #162235;
  --max: 1200px;
  --radius: 10px;
  --shadow: 0 16px 40px rgba(10, 22, 40, 0.12);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(100% - 48px, var(--max)); margin: 0 auto; }
.section { padding: 72px 0; }
.section.tight { padding: 52px 0; }
.eyebrow { text-transform: uppercase; letter-spacing: .08em; font-size: .78rem; color: var(--accent); font-weight: 700; }
h1,h2,h3,h4 { font-family: "Playfair Display", Georgia, serif; margin: 0 0 14px; color: var(--navy); line-height: 1.2; }
h1 { font-size: clamp(2rem, 4vw, 3.5rem); }
h2 { font-size: clamp(1.7rem, 3vw, 2.4rem); }
h3 { font-size: 1.25rem; }
p { margin: 0 0 14px; color: var(--gray-700); }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 20px; border-radius: 999px; font-weight: 600;
  border: 1px solid transparent; transition: .2s ease;
}
.btn-primary { background: var(--accent-gold); color: var(--navy); }
.btn-primary:hover { background: #b69556; }
