header.site-header { position: sticky; top: 0; z-index: 200; background: rgba(255,255,255,.97); border-bottom: 1px solid var(--gray-100); }
.nav-wrap { display: flex; align-items: center; justify-content: space-between; min-height: 76px; }
.logo { font-weight: 800; font-size: 1.35rem; color: var(--navy); letter-spacing: .02em; }
.logo span { color: var(--accent-gold); }
nav.main-nav { display: flex; align-items: center; gap: 24px; }
.nav-link { font-weight: 600; color: var(--navy); padding: 28px 0; }
.nav-item { position: relative; }
.mega-menu {
  position: absolute; left: 0; top: calc(100% + 8px); width: 860px;
  background: #fff; border: 1px solid var(--gray-100); border-radius: 14px;
  box-shadow: var(--shadow); padding: 28px; display: none;
  grid-template-columns: 1.2fr 1fr; gap: 28px;
}
.nav-item.open .mega-menu { display: grid; }
.mega-col h4 { font-family: Inter, sans-serif; font-size: .85rem; text-transform: uppercase; letter-spacing: .07em; margin-bottom: 16px; color: var(--gray-500); }
.mega-list { display: grid; gap: 10px; }
.mega-list a { padding: 10px 12px; border-radius: 8px; border: 1px solid transparent; }
.mega-list a:hover { background: var(--gray-50); border-color: var(--gray-100); color: var(--accent); }
.mobile-toggle { display: none; border: none; background: none; font-size: 1.5rem; }
