}
.mobile-accordion-content { display: none; padding-bottom: 12px; }
.mobile-accordion-content.open { display: block; }
.mobile-sub-link { display: block; padding: 8px 0 8px 12px; color: var(--gray-700); }
.hero {
  position: relative; min-height: 72vh; display: grid; align-items: end; color: white;
  background-size: cover; background-position: center;
}
.hero::before { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, rgba(10,22,40,.88), rgba(10,22,40,.45)); }
.hero-content { position: relative; padding: 86px 0 70px; max-width: 720px; }
.hero h1, .hero p { color: #fff; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 22px; }
.grid-2 { display: grid; grid-template-columns: repeat(2,1fr); gap: 22px; }
.card { background: #fff; border: 1px solid var(--gray-100); border-radius: var(--radius); padding: 24px; }
.card h3 { margin-bottom: 10px; }
.tag { display: inline-block; font-size: .73rem; letter-spacing: .06em; text-transform: uppercase; padding: 6px 10px; border-radius: 999px; background: #eef4fa; color: var(--gray-700); margin-bottom: 10px; }
.what-we-do { display: grid; grid-template-columns: 280px 1fr; gap: 26px; }
.tabs-vertical { display: grid; gap: 10px; }
.tab-btn {
  border: 1px solid var(--gray-200); border-radius: 10px; background: #fff;
  text-align: left; padding: 16px; font-weight: 700; color: var(--navy); cursor: pointer;
}
.tab-btn.active { border-color: var(--accent); background: #f2fbfb; color: var(--accent); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.newsletter { background: var(--navy); color: #d9e2ef; border-radius: 16px; padding: 34px; }
.newsletter h2, .newsletter p { color: #fff; }
.newsletter form { display: flex; gap: 10px; flex-wrap: wrap; }
.newsletter input { flex: 1 1 260px; padding: 12px 14px; border-radius: 999px; border: none; }
.footer { background: var(--navy); color: #d2dbea; margin-top: 60px; }
.footer .container { padding: 50px 0 26px; display: grid; gap: 24px; }
.footer-grid { display: grid; grid-template-columns: 1.1fr 1fr 1fr 1fr; gap: 20px; }
.footer h4 { color: #fff; font-family: Inter,sans-serif; margin-bottom: 10px; }
.page-hero { min-height: 48vh; }
.breadcrumb { font-size: .86rem; color: #d9e2ef; margin-bottom: 12px; }
.sidebar-layout { display: grid; grid-template-columns: 2.1fr 1fr; gap: 30px; }
.list-links { display: grid; gap: 12px; }
.list-links a { padding: 10px 12px; border: 1px solid var(--gray-100); border-radius: 8px; }
.list-links a:hover { color: var(--accent); border-color: var(--accent); }
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform .35s ease; }
.slide { min-width: 100%; }
.carousel-controls { display: flex; gap: 10px; margin-top: 14px; }
.carousel-controls button { border: 1px solid var(--gray-200); background: #fff; padding: 8px 12px; border-radius: 8px; }
@media (max-width: 1024px) {
  nav.main-nav { display: none; }
  .mobile-toggle { display: inline-block; }
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .what-we-do { grid-template-columns: 1fr; }
  .sidebar-layout { grid-template-columns: 1fr; }
}
@media (max-width: 700px) {
  .container { width: min(100% - 30px, var(--max)); }
  .grid-3,.grid-2 { grid-template-columns: 1fr; }
  .hero { min-height: 62vh; }
}
EOF

cat > /app/output/script.js <<'EOF'
const servicesItem = document.querySelector('[data-services-item]');
const servicesToggle = document.querySelector('[data-services-toggle]');
if (servicesItem && servicesToggle) {
  const open = () => servicesItem.classList.add('open');
  const close = () => servicesItem.classList.remove('open');
  servicesToggle.addEventListener('click', (event) => {
    event.preventDefault();
    servicesItem.classList.toggle('open');
  });
  servicesItem.addEventListener('mouseenter', open);
  servicesItem.addEventListener('mouseleave', close);
  document.addEventListener('click', (event) => {
    if (!servicesItem.contains(event.target)) close();
  });
}

const mobileToggle = document.querySelector('[data-mobile-toggle]');
const mobilePanel = document.querySelector('[data-mobile-panel]');
if (mobileToggle && mobilePanel) {
  mobileToggle.addEventListener('click', () => {
    mobilePanel.classList.toggle('open');
  });
}

document.querySelectorAll('[data-accordion]').forEach((button) => {
  button.addEventListener('click', () => {
    const panel = button.nextElementSibling;
    panel.classList.toggle('open');
  });
});

document.querySelectorAll('[data-tabs]').forEach((tabWrap) => {
  const buttons = tabWrap.querySelectorAll('[data-tab-btn]');
  const panels = tabWrap.querySelectorAll('[data-tab-panel]');
  buttons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const id = btn.dataset.tabBtn;
      buttons.forEach((b) => b.classList.remove('active'));
      panels.forEach((p) => p.classList.remove('active'));
      btn.classList.add('active');
      tabWrap.querySelector(`[data-tab-panel="${id}"]`)?.classList.add('active');
    });
  });
});

const carousel = document.querySelector('[data-carousel]');
if (carousel) {
  const track = carousel.querySelector('[data-carousel-track]');
  const slides = carousel.querySelectorAll('.slide');
  let index = 0;
  const render = () => track.style.transform = `translateX(-${index * 100}%)`;
  carousel.querySelector('[data-prev]')?.addEventListener('click', () => {
    index = (index - 1 + slides.length) % slides.length;
    render();
  });
  carousel.querySelector('[data-next]')?.addEventListener('click', () => {
    index = (index + 1) % slides.length;
    render();
  });
}
EOF

